import{_ as e,o as l,c as a,a0 as s}from"./chunks/framework.DQOulFGV.js";const p=JSON.parse('{"title":"第3章 监控告警","description":"","frontmatter":{},"headers":[],"relativePath":"redis/05-operations/chapter-03-monitoring.md","filePath":"redis/05-operations/chapter-03-monitoring.md"}'),i={name:"redis/05-operations/chapter-03-monitoring.md"};function d(n,t,r,h,o,g){return l(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="第3章-监控告警" tabindex="-1">第3章 监控告警 <a class="header-anchor" href="#第3章-监控告警" aria-label="Permalink to &quot;第3章 监控告警&quot;">​</a></h1><blockquote><p>监控是运维的「眼睛」。完善的监控体系能在故障发生前预警，在故障发生后提供定位依据。本章讲解监控维度、关键指标与告警阈值。</p></blockquote><hr><h2 id="_3-1-监控维度" tabindex="-1">3.1 监控维度 <a class="header-anchor" href="#_3-1-监控维度" aria-label="Permalink to &quot;3.1 监控维度&quot;">​</a></h2><p>Redis 监控从三个维度构建：</p><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;">服务端</td><td style="text-align:left;">操作系统层面：CPU、内存、网络、磁盘</td></tr><tr><td style="text-align:left;">应用端</td><td style="text-align:left;">Redis 自身：QPS、延迟、内存、连接、命中率</td></tr><tr><td style="text-align:left;">联合分析</td><td style="text-align:left;">服务端与应用端数据交叉定位问题</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>服务端（OS）     应用端（Redis）      联合分析</span></span>
<span class="line"><span>CPU / 内存    →  QPS / 延迟      →  定位根因</span></span>
<span class="line"><span>网络 / 磁盘   →  内存 / 命中率    →  关联证据</span></span></code></pre></div><hr><h2 id="_3-2-关键指标" tabindex="-1">3.2 关键指标 <a class="header-anchor" href="#_3-2-关键指标" aria-label="Permalink to &quot;3.2 关键指标&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">指标</th><th style="text-align:left;">含义</th><th style="text-align:left;">重要性</th></tr></thead><tbody><tr><td style="text-align:left;">QPS</td><td style="text-align:left;">每秒请求数</td><td style="text-align:left;">高（吞吐基线）</td></tr><tr><td style="text-align:left;">延迟</td><td style="text-align:left;">命令响应时间</td><td style="text-align:left;">高（用户体验）</td></tr><tr><td style="text-align:left;">内存使用率</td><td style="text-align:left;">used_memory / maxmemory</td><td style="text-align:left;">高（OOM 风险）</td></tr><tr><td style="text-align:left;">碎片率</td><td style="text-align:left;">mem_fragmentation_ratio</td><td style="text-align:left;">中（内存浪费）</td></tr><tr><td style="text-align:left;">命中率</td><td style="text-align:left;">keyspace 命中比例</td><td style="text-align:left;">中（缓存效果）</td></tr><tr><td style="text-align:left;">fork 耗时</td><td style="text-align:left;">latest_fork_usec</td><td style="text-align:left;">中（fork 停顿）</td></tr><tr><td style="text-align:left;">连接数</td><td style="text-align:left;">当前连接数</td><td style="text-align:left;">中（连接耗尽）</td></tr><tr><td style="text-align:left;">复制延迟</td><td style="text-align:left;">主从 offset 差</td><td style="text-align:left;">中（数据不一致）</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stats</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # QPS、命中率</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> memory</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 内存、碎片率</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> replication</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 复制延迟</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clients</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 连接数</span></span></code></pre></div><hr><h2 id="_3-3-告警阈值" tabindex="-1">3.3 告警阈值 <a class="header-anchor" href="#_3-3-告警阈值" aria-label="Permalink to &quot;3.3 告警阈值&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">指标</th><th style="text-align:left;">告警阈值（参考）</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">内存使用率</td><td style="text-align:left;">&gt; 80%</td><td style="text-align:left;">接近上限，需扩容或淘汰</td></tr><tr><td style="text-align:left;">碎片率</td><td style="text-align:left;">&gt; 1.5</td><td style="text-align:left;">碎片较多，考虑整理</td></tr><tr><td style="text-align:left;">慢查询数量</td><td style="text-align:left;">持续增长</td><td style="text-align:left;">存在慢命令</td></tr><tr><td style="text-align:left;">fork 耗时</td><td style="text-align:left;">&gt; 1 秒</td><td style="text-align:left;">fork 停顿明显</td></tr><tr><td style="text-align:left;">连接数</td><td style="text-align:left;">&gt; 80% maxclients</td><td style="text-align:left;">连接接近上限</td></tr><tr><td style="text-align:left;">命中率</td><td style="text-align:left;">显著下降</td><td style="text-align:left;">缓存失效或穿透</td></tr></tbody></table><blockquote><p>阈值需结合业务实际情况调整。告警的黄金法则是「宁可在故障前预警，不要在故障后才知道」。</p></blockquote><hr><h2 id="_3-4-可视化方案" tabindex="-1">3.4 可视化方案 <a class="header-anchor" href="#_3-4-可视化方案" aria-label="Permalink to &quot;3.4 可视化方案&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">方案</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">CacheCloud</td><td style="text-align:left;">搜狐开源的 Redis 私有云平台，一站式管理</td></tr><tr><td style="text-align:left;">Prometheus + Grafana</td><td style="text-align:left;">通过 redis_exporter 采集指标，Grafana 可视化</td></tr><tr><td style="text-align:left;">云厂商监控</td><td style="text-align:left;">各云厂商自带 Redis 监控面板</td></tr><tr><td style="text-align:left;">自建采集</td><td style="text-align:left;">定时执行 INFO，上报到自研监控平台</td></tr></tbody></table><p>选择建议：中小团队用云厂商自带监控或 Prometheus + Grafana；需要多实例统一管理、权限控制等能力时考虑 CacheCloud 这类平台。</p>`,19)])])}const f=e(i,[["render",d]]);export{p as __pageData,f as default};
